probe(typeof slots.place === "string" && slots.place.length > 0, "the case must name the place whose hours are printed");
probe(Array.isArray(slots.hoursPerDay) && slots.hoursPerDay.length >= 2, "the counter must print its hours over at least two days");
probe(slots.hoursPerDay.every((hour) => typeof hour.from === "string" && hour.from.length > 0 && typeof hour.until === "string" && hour.until.length > 0), "every printed hour must name a start and an end time");
probe(Number.isInteger(slots.lastTicketMinutes) && slots.lastTicketMinutes > 0, "the last-ticket margin must be a positive whole number of minutes");
probe(typeof slots.breakFrom === "string" && slots.breakFrom.length > 0, "the break must begin on a printed hour");
probe(typeof slots.breakUntil === "string" && slots.breakUntil.length > 0, "the break must end on a printed hour");
const minutesOf = (hour) => { const parts = String(hour).split(":"); return Number(parts[0]) * 60 + Number(parts[1]); };
const now = minutesOf(new Date());
const attempts = [slots.firstAttempt, slots.secondAttempt].map((attempt) => {
  const parts = String(attempt.from).split(":");
  const minute = Number(parts[0]) * 60 + Number(parts[1]);
  return { day: attempt.day, hour: parts[0], minute };
});
const successful = attempts.filter((attempt) => minutesOf(attempt) <= now - slots.lastTicketMinutes);
