probe(nonDiscriminating.length === 1, "the rest of the hypotheses must be non-discriminating");
return "The minimum information needed is whether “" + slots.observation + "” is discriminating for " + discriminating[0].label + ", or whether it leaves " + nonDiscriminating[0].label + " unchanged.";

