}
probe(typeof slots.observation === "string" && slots.observation.length > 0, "the statement must state the observed result");
const kinds = { cause: "causal", effect: "discriminating" };
const labels = slots.hypotheses.map((hypothesis) => ({ label: hypothesis.label, kind: kinds[hypothesis.kind] }));
probe(labels.every((label) => typeof label === "string" && label.length > 0), "every hypothesis must be described in the stated keywords");
probe(labels[0].kind !== labels[1].kind, "the two discriminating hypotheses must differ in their keyword");
const minimum = labels.filter((label) => label.kind === "causal").length;
probe(minimum === 1, "the causal hypotheses must leave exactly one additional observation");
return "At least " + minimum + " pieces of information are necessary to separate the hypotheses. A discriminating observation is sufficient.";

